<template><div class="form-view"><div class="form-heading"><span class="form-kicker">{{ local("Open invitation") }}</span><h2>{{ local("Create your account") }}</h2><p>{{ local("Invite codes help protect the quality of the Creator SN community.") }}</p></div><form @submit.prevent="submit"><label>{{ local("Account") }}<input v-model.trim="form.userid" autocomplete="username" :placeholder="local('Account or email')" /></label><label>{{ local("Password") }}<input v-model="form.pwd" type="password" autocomplete="new-password" :placeholder="local('At least 6 characters')" /></label><label>{{ local("Confirm password") }}<input v-model="confirm" type="password" autocomplete="new-password" /></label><label>{{ local("Invite code") }}<input v-model.trim="form.invite_code" :placeholder="local('Enter invite code')" /></label><p v-if="error" class="error">{{ error }}</p><p v-if="success" class="success">{{ local("Registration succeeded, returning to sign in…") }}</p><button class="primary-button" :disabled="loading">{{ loading ? local("Registering…") : local("Create account") }}</button></form><div class="form-foot"><span>{{ local("Already have an account?") }}</span><router-link to="/login">{{ local("Back to sign in") }}</router-link></div></div></template>
<script setup>
import { reactive,ref } from "vue";import { useRouter } from "vue-router";import { UserApi } from "@/api";import { useAppStore } from "@/store";
const router=useRouter(),form=reactive({userid:"",pwd:"",invite_code:""}),confirm=ref(""),loading=ref(false),error=ref(""),success=ref(false);
const local = useAppStore().local;
async function submit(){error.value="";if(!form.userid||!form.pwd||!form.invite_code){error.value=local("Please complete the registration form");return}if(form.pwd.length<6){error.value=local("Password must be at least 6 characters");return}if(form.pwd!==confirm.value){error.value=local("Passwords do not match");return}loading.value=true;try{const result=await UserApi.register(form);if(result.code!==200)throw new Error(result.message||local("Registration failed"));success.value=true;setTimeout(()=>router.push("/login"),700)}catch(e){error.value=e.message||local("Registration failed")}finally{loading.value=false}}
</script>
<style scoped lang="scss">.form-view{display:grid;gap:24px}.form-heading h2{margin:8px 0;font-size:28px}.form-heading p{margin:0;color:#817b93}.form-kicker{font-size:11px;color:#b25fba;letter-spacing:.16em;font-weight:800}form{display:grid;gap:14px}label{display:grid;gap:7px;font-size:13px;color:#504867;font-weight:700}input{width:100%;padding:12px 14px;border:1px solid #e1d8ee;border-radius:12px;background:rgba(255,255,255,.8);font:inherit;outline:none}.primary-button{padding:14px;border:0;border-radius:12px;background:linear-gradient(120deg,#9c69d7,#e27bc7);color:#fff;font-weight:800;font-size:15px;cursor:pointer}.error{color:#ba4e70;font-size:13px}.success{color:#438d72;font-size:13px}.form-foot{font-size:13px;color:#817b93}.form-foot a{margin-left:6px;color:#8759b6;font-weight:700;text-decoration:none}</style>
